    def __init__(self, problem, inst):
        self.problem = problem
        self.inst = inst

    def destroy(self, sol, ratio: float, rng: Random) -> tuple[Any, set[str]]:
        assignment = self.problem.to_assignment(sol)
        routes = [tuple(r) for r in sol if r]
        if not routes:
            return assignment, set()

        # Elegimos una ruta semilla, pero el tamaño liberado crece monótonamente con ratio.
        seed_route = rng.choice(routes)
        route_len = len(seed_route)

        target = max(1, min(self.inst.n_customers, int(ceil(ratio * self.inst.n_customers))))

        block: set[int] = set(seed_route)
        if len(block) < target:
