            rng.shuffle(other_customers)
            for c in other_customers:
                if len(block) >= target:
                    break
                block.add(c)

        if len(block) < target:
            # Si aún faltan clientes, tomamos clientes no usados de forma global.
            used = set(block)
            remaining = [c for c in range(1, self.inst.n_customers + 1) if c not in used]
            rng.shuffle(remaining)
            for c in remaining:
                if len(block) >= target:
                    break
                block.add(c)

        free_vars: set[str] = set()
        for name in assignment:
            _, a, b = name.split("_")
            i, j = int(a), int(b)
            if i in block or j in block:
                free_vars.add(name)

        if not free_vars:
            c = seed_route[0]
            for j in range(self.inst.n_customers + 1):
                if j != c:
                    free_vars.add(f"x_{c}_{j}")
                    free_vars.add(f"x_{j}_{c}")

        partial = {v: val for v, val in assignment.items() if v not in free_vars}
        return partial, free_vars


